function fmt(text,learned){
  let out="";
  for(const ch of text){
    if(/[\u4E00-\u9FFF]/.test(ch)&&!learned.has(ch)){out+=YOMI[ch]||ch;}
    else{out+=ch;}
  }
  return out;
}

